<script setup lang="ts">
import { computed, ref, watch, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { useFitness, tone, asset } from './store'
import { addDays, clone, dayOn, newDay, volume, setCount, type TrainingRecord, type FitnessItem } from '../../../shared/fitness'
import { localDate } from '../../../shared/date'
import { confirmDelete, unwrap, report } from '../lib/api'
import ItemEditor from './ItemEditor.vue'
import FitnessChart from './FitnessChart.vue'
import AppIcon from '../components/AppIcon.vue'
import DesignArt from './DesignArt.vue'
const props=defineProps<{page:string}>(),emit=defineEmits<{navigate:[page:string]}>(),fs=useFitness(),today=localDate()
const month=ref(today.slice(0,7)),selectedDate=ref(today),dateFrom=ref(month.value+'-01'),dateTo=ref(today),query=ref(''),type=ref('全部'),source=ref('全部'),pageNumber=ref(1),selectedId=ref(''),checked=ref<string[]>([]),group=ref('按周'),metric=ref('容量'),comparePrevious=ref(false),previewRecord=ref(false),summaryOnly=ref(false),recordForm=ref<HTMLFormElement>(),imported=ref<TrainingRecord[]>([]),importError=ref(''),showDifference=ref(false),showPlan=ref(false),exportFormat=ref('csv')
const blankRecord=():TrainingRecord=>({id:crypto.randomUUID(),date:today,title:'',type:'自定义',minutes:null,notes:'',tags:'',source:'手动补录',items:[],updated:new Date().toISOString()})
const draft=ref<TrainingRecord>(blankRecord()),recordTemplate=ref(''),sourceMode=ref('空白补录'),originalItems=ref<FitnessItem[]>([])
const allRecords=computed(()=>[...fs.data.records].sort((a,b)=>b.date.localeCompare(a.date))),filtered=computed(()=>allRecords.value.filter(r=>r.date>=dateFrom.value&&r.date<=dateTo.value&&(type.value==='全部'||r.type===type.value)&&(source.value==='全部'||r.source===source.value)&&(r.title+r.notes+r.items.map(i=>fs.exercise(i.exerciseId)?.name).join(' ')).toLowerCase().includes(query.value.toLowerCase()))),monthRecords=computed(()=>allRecords.value.filter(r=>r.date.startsWith(month.value)&&(type.value==='全部'||r.type===type.value))),calendarRecords=computed(()=>monthRecords.value.filter(r=>r.date===selectedDate.value)),detail=computed(()=>allRecords.value.find(r=>r.id===selectedId.value)||(props.page==='list'?allRecords.value[0]:calendarRecords.value[0]))
watch([dateFrom,dateTo,query,type,source],()=>pageNumber.value=1)
watch(()=>props.page,p=>{if(p==='entry'&&!editingId.value){draft.value=blankRecord();summaryOnly.value=false;sourceMode.value='空白补录'}if(p!=='entry')editingId.value=''} )
const editingId=ref('')
onMounted(()=>{if(allRecords.value.length){selectedDate.value=allRecords.value[0].date;selectedId.value=allRecords.value[0].id}})
watch(()=>props.page,p=>{if(p==='list'&&!selectedId.value)selectedId.value=allRecords.value[0]?.id||''})
const calendar=computed(()=>{const first=month.value+'-01',weekday=(new Date(first+'T12:00:00').getDay()+6)%7;return Array.from({length:Math.ceil((weekday+new Date(Number(month.value.slice(0,4)),Number(month.value.slice(5)),0).getDate())/7)*7},(_,i)=>addDays(first,i-weekday))})
function shiftMonth(n:number):void{const d=new Date(month.value+'-01T12:00:00');d.setMonth(d.getMonth()+n);month.value=localDate(d).slice(0,7)}
function chooseDate(d:string):void{selectedDate.value=d;selectedId.value=monthRecords.value.find(r=>r.date===d)?.id||''}
function newRecord(date=today):void{editingId.value='new';draft.value=blankRecord();draft.value.date=date;summaryOnly.value=false;sourceMode.value='空白补录';emit('navigate','entry')}
function edit(r:TrainingRecord):void{editingId.value=r.id;draft.value=clone(r);summaryOnly.value=!r.items.length;originalItems.value=clone(r.items);emit('navigate','entry')}
function copy(r:TrainingRecord):void{edit(r);draft.value.id=crypto.randomUUID();draft.value.date=today;editingId.value='new'}
async function remove(r:TrainingRecord):Promise<void>{if(await confirmDelete(r.title)){fs.data.records=fs.data.records.filter(x=>x.id!==r.id);selectedId.value='';await fs.save('记录已删除')}}
function bring(mode:string):void{sourceMode.value=mode;if(mode==='空白补录'){draft.value.items=[];return}const d=mode==='从计划带入'?dayOn(fs.data,draft.value.date):fs.data.templates.find(t=>t.id===recordTemplate.value);if(d){draft.value.title=d.title;draft.value.type=d.type;draft.value.items=clone(d.items);originalItems.value=clone(d.items)}}
async function saveRecord():Promise<void>{if(!recordForm.value?.reportValidity())return;const r=clone(draft.value);r.minutes=r.minutes==null||String(r.minutes)===''?null:Number(r.minutes);r.items=summaryOnly.value?[]:r.items;r.items.forEach(i=>i.sets.forEach(s=>(Object.keys(s) as (keyof typeof s)[]).forEach(k=>s[k]=s[k]==null||String(s[k])===''?null:Number(s[k]))));r.updated=new Date().toISOString();const index=fs.data.records.findIndex(x=>x.id===r.id);if(index<0)fs.data.records.push(r);else fs.data.records[index]=r;if(await fs.save('训练记录已保存')){selectedId.value=r.id;selectedDate.value=r.date;month.value=r.date.slice(0,7);emit('navigate','calendar')}}
const types=computed(()=>[...new Set(filtered.value.map(r=>r.type))]),totalVolume=computed(()=>volume(filtered.value.flatMap(r=>r.items))),minutes=computed(()=>filtered.value.reduce((a,r)=>a+(r.minutes||0),0)),durationCount=computed(()=>filtered.value.filter(r=>r.minutes!==null).length)
const buckets=computed(()=>{const result:{label:string;records:TrainingRecord[]}[]=[];let d=dateFrom.value;let step=group.value==='按周期'?fs.data.rhythm.length:group.value==='按月'?30:7;for(let i=0;d<=dateTo.value;i++){const next=group.value==='按月'?(()=>{const dt=new Date(d+'T12:00:00');dt.setMonth(dt.getMonth()+1);dt.setDate(1);return localDate(dt)})():addDays(d,step);result.push({label:d.slice(5).replace('-','.'),records:filtered.value.filter(r=>r.date>=d&&r.date<next)});d=next}return result})
const chartLabels=computed(()=>buckets.value.map(b=>b.label)),chartSeries=computed(()=>['推','拉','腿',...new Set(filtered.value.map(r=>r.type).filter(t=>!['推','拉','腿'].includes(t)))].filter(t=>filtered.value.some(r=>r.type===t)).map((t,i)=>({name:t,color:['#79d4b0','#aaa0ed','#ffc18e'][i],values:buckets.value.map(b=>b.records.filter(r=>r.type===t).length)}))),trend=computed(()=>buckets.value.map(b=>metric.value==='容量'?volume(b.records.flatMap(r=>r.items))/1000:metric.value==='时长'?b.records.reduce((a,r)=>a+(r.minutes||0),0):b.records.length))
const proportions=computed(()=>['推','拉','腿',...types.value.filter(t=>!['推','拉','腿'].includes(t))].filter(t=>types.value.includes(t)).map((t,i)=>({type:t,count:filtered.value.filter(r=>r.type===t).length,color:['#79d4b0','#aaa0ed','#ffc18e','#9ec5ee','#e4b0d0'][i%5]}))),donut=computed(()=>{let n=0;return 'conic-gradient('+proportions.value.map(p=>{const a=n;n+=p.count/filtered.value.length*100;return `${p.color} ${a}% ${n}%`}).join(',')+')'})
const previous=computed(()=>{const len=Math.round((Date.parse(dateTo.value)-Date.parse(dateFrom.value))/86400000)+1;return allRecords.value.filter(r=>r.date>=addDays(dateFrom.value,-len)&&r.date<dateFrom.value&&(type.value==='全部'||r.type===type.value))})
const actionId=ref(''),actionMetric=ref('最高工作重量'),aId=ref(''),bId=ref('')
const actions=computed(()=>[...new Set(filtered.value.flatMap(r=>r.items.map(i=>i.exerciseId)))].map(id=>fs.exercise(id)).filter(Boolean)),actionHistory=computed(()=>filtered.value.filter(r=>r.items.some(i=>i.exerciseId===actionId.value&&i.sets.some(s=>{const measure=fs.exercise(actionId.value)?.measure;if(measure==='time')return s.duration!==null&&String(s.duration)!=='';if(measure==='distance')return s.distance!==null&&String(s.distance)!=='';return actionMetric.value==='总次数'?s.reps!==null&&String(s.reps)!=='':actionMetric.value==='训练容量'?s.weight!==null&&s.reps!==null&&String(s.weight)!==''&&String(s.reps)!=='':s.weight!==null&&String(s.weight)!==''}))).sort((a,b)=>a.date.localeCompare(b.date))),actionItems=(r:TrainingRecord)=>r.items.filter(i=>i.exerciseId===actionId.value),maxWeight=(r:TrainingRecord)=>fs.exercise(actionId.value)?.measure==='time'?actionItems(r).reduce((a,i)=>a+i.sets.reduce((n,s)=>n+(s.duration||0),0),0):fs.exercise(actionId.value)?.measure==='distance'?actionItems(r).reduce((a,i)=>a+i.sets.reduce((n,s)=>n+(s.distance||0),0),0):Math.max(0,...actionItems(r).flatMap(i=>i.sets.map(s=>s.weight||0))),reps=(r:TrainingRecord)=>actionItems(r).reduce((a,i)=>a+i.sets.reduce((a,s)=>a+(s.reps||0),0),0)
const actionUnit=computed(()=>fs.exercise(actionId.value)?.measure==='time'?'秒':fs.exercise(actionId.value)?.measure==='distance'?'米':'kg'),actionOptions=computed(()=>actionUnit.value==='kg'?['最高工作重量','总次数','训练容量']:[actionUnit.value==='秒'?'总时长':'总距离'])
watch(actionId,()=>{actionMetric.value=actionOptions.value[0]})
const actionValues=computed(()=>actionHistory.value.map(r=>actionMetric.value==='最高工作重量'||actionMetric.value==='总时长'||actionMetric.value==='总距离'?maxWeight(r):actionMetric.value==='总次数'?reps(r):volume(actionItems(r)))),actionA=computed(()=>actionHistory.value.find(r=>r.id===aId.value)||actionHistory.value[0]),actionB=computed(()=>actionHistory.value.find(r=>r.id===bId.value)||actionHistory.value.at(-1))
watch(actions,a=>{if(!a.some(e=>e.id===actionId.value))actionId.value=a[0]?.id||''},{immediate:true})
function download(content:string,name:string,_mime:string):void{void window.workbench.fitness.exportFile(name,content).then(result=>{if(unwrap(result))ElMessage.success('已导出')}).catch(report)}
const csvCell=(s:unknown)=>'"'+String(s??'').replace(/"/g,'""')+'"'
function exportRecords(template=false):void{if(props.page==='compare'&&!template){download('\ufeff'+[['日期','动作','记录值', '单位','总次数','组数','容量kg'],...actionHistory.value.map(r=>[r.date,fs.exercise(actionId.value)?.name,maxWeight(r),actionUnit.value,reps(r),setCount(actionItems(r)),volume(actionItems(r))])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'动作对比.csv','text/csv;charset=utf-8');return}if(template){download('\ufeff日期,训练名称,类型,分钟,备注,动作明细JSON\r\n2026-10-29,背部训练,拉,55,示例（导入前删除此行）,[]','训练记录导入模板.csv','text/csv;charset=utf-8');return}const rows=checked.value.length?filtered.value.filter(r=>checked.value.includes(r.id)):filtered.value;if(exportFormat.value==='json'){download(JSON.stringify(rows,null,2),'训练记录.json','application/json');return}download('\ufeff'+[['日期','训练名称','类型','分钟','备注','动作明细JSON'],...rows.map(r=>[r.date,r.title,r.type,r.minutes,r.notes,JSON.stringify(r.items)])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'训练记录.csv','text/csv;charset=utf-8')}
function parseCSV(text:string):string[][]{const rows:string[][]=[];let row:string[]=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
async function importFile(event:Event):Promise<void>{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;importError.value='';try{const text=(await file.text()).replace(/^\uFEFF/,'');let records:TrainingRecord[];if(file.name.toLowerCase().endsWith('.json'))records=JSON.parse(text);else{const [header,...rows]=parseCSV(text);if(!header.includes('日期')||!header.includes('训练名称'))throw new Error('CSV需要“日期”和“训练名称”列，可下载模板。');records=rows.map(row=>{const value=(key:string)=>row[header.indexOf(key)]||'';return {...blankRecord(),date:value('日期'),title:value('训练名称'),type:value('类型')||'自定义',minutes:value('分钟')?Number(value('分钟')):null,notes:value('备注'),items:value('动作明细JSON')?JSON.parse(value('动作明细JSON')):[]}})}if(!Array.isArray(records))throw new Error('请选择记录数组格式的JSON。');for(const r of records){if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!r.title?.trim()||!Array.isArray(r.items))throw new Error('记录需要有效日期、训练名称和动作明细数组。');for(const item of r.items)if(!fs.exercise(item.exerciseId))throw new Error('动作库找不到动作 '+item.exerciseId+'，请先创建对应动作。')}imported.value=records.map(r=>({...blankRecord(),...r,id:crypto.randomUUID(),source:'导入'}))}catch(e){importError.value=(e as Error).message;imported.value=[]}(event.target as HTMLInputElement).value=''}
async function commitImport():Promise<void>{fs.data.records.push(...imported.value);if(await fs.save('记录已导入'))imported.value=[]}
function exportChart(event?:Event):void{const original=event?(event.currentTarget as HTMLElement).closest('.fit-card')!.querySelector('svg')!:document.querySelector('.fit-volume-card svg')!;const svg=original.cloneNode(true) as SVGElement;const children=[original,...original.querySelectorAll('*')],copies=[svg,...svg.querySelectorAll('*')];children.forEach((e,i)=>{const style=getComputedStyle(e);if(e.tagName==='text')copies[i].setAttribute('fill',style.fill);if(e.tagName==='line')copies[i].setAttribute('stroke',style.stroke)});svg.setAttribute('xmlns','http://www.w3.org/2000/svg');download(new XMLSerializer().serializeToString(svg),'训练趋势.svg','image/svg+xml')}
function preset(value:string):void{dateTo.value=today;dateFrom.value=value==='month'?today.slice(0,7)+'-01':addDays(today,-29)}
defineExpose({newRecord,importFile,exportRecords,saveRecord,exportChart})
</script>
<template>
 <div class="fit-records-pane">
 <template v-if="page!=='entry'">
 <div class="fit-record-toolbar" v-if="page==='stats'"><div class="fit-filter-chips"><label>日期 <el-date-picker v-model="dateFrom" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/> — <el-date-picker v-model="dateTo" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/></label><span class="fit-period-presets"><button @click="preset('30')">最近30天</button><button @click="preset('month')">本月</button></span><label class="fit-period-compare"><input type="checkbox" v-model="comparePrevious"/> 与上一时段对比</label></div></div>
 <section v-if="imported.length||importError" class="fit-card fit-import-preview"><h2>导入预览</h2><p v-if="importError" class="fit-error">{{ importError }}</p><template v-else><p>共 {{ imported.length }} 条记录，确认后保存。</p><table class="fit-table"><tbody><tr v-for="r in imported.slice(0,8)"><td>{{ r.date }}</td><td>{{ r.title }}</td><td>{{ r.items.length }}个动作</td></tr></tbody></table><div class="fit-actions"><button class="fit-primary" @click="commitImport">确认导入</button><button class="fit-button" @click="imported=[]">取消</button></div></template></section>
 </template>
 <div v-if="page==='calendar'" class="fit-calendar-columns"><section class="fit-card"><nav class="fit-sub-tabs"><button v-for="[id,label,icon] in [['calendar','日历','calendar'],['stats','统计','grid'],['compare','动作对比','list'],['list','明细','document']]" :class="{active:page===id}" @click="emit('navigate',id)"><AppIcon :name="icon" :size="18"/>{{ label }}</button></nav><header><div class="fit-cycle-nav"><button @click="shiftMonth(-1)">‹</button><el-date-picker v-model="month" type="month" format="YYYY 年 M 月" value-format="YYYY-MM" :clearable="false"/><button @click="shiftMonth(1)">›</button></div><button class="fit-button" @click="month=today.slice(0,7)">本月</button><div class="fit-calendar-types"><span>类型</span><button v-for="t in ['全部','推','拉','腿','有氧']" :class="{active:type===t}" @click="type=t">{{ t }}</button></div><label class="fit-muted"><input type="checkbox" v-model="showPlan"/> 显示计划参考</label></header><div class="fit-calendar-week"><b v-for="w in ['一','二','三','四','五','六','日']">{{ w }}</b></div><div class="fit-calendar-grid"><button v-for="d in calendar" :key="d" class="fit-calendar-day" :class="{outside:!d.startsWith(month),selected:d===selectedDate,today:d===today}" @click="chooseDate(d)"><span>{{ Number(d.slice(8)) }}<small v-if="d===today">今天</small></span><div v-for="r in monthRecords.filter(r=>r.date===d)" class="fit-calendar-record" :class="tone(r.type)">{{ r.title }}</div><small v-if="showPlan&&dayOn(fs.data,d)" class="fit-planned">计划：{{ dayOn(fs.data,d)?.title }}</small></button></div><footer class="fit-calendar-legend"><span v-for="t in ['推','拉','腿']" :class="tone(t)">{{ t }} {{ monthRecords.filter(r=>r.type===t).length }}次</span><small>无记录不等于休息或未训练。</small></footer></section><aside class="fit-side-column"><section class="fit-card"><h2>{{ Number(selectedDate.slice(5,7)) }} 月 {{ Number(selectedDate.slice(8)) }} 日 <small>{{ new Date(selectedDate+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'long'}) }}</small></h2><template v-if="calendarRecords.length"><select v-if="calendarRecords.length>1" v-model="selectedId"><option v-for="r in calendarRecords" :value="r.id">{{ r.title }}</option></select><div v-if="detail"><h2 class="fit-detail-title">{{ detail.title }} <small class="fit-badge">{{ detail.source }}</small></h2><div class="fit-record-metrics"><span>{{ detail.items.length }} 个动作</span><span>{{ setCount(detail.items) }} 组</span><span>{{ detail.minutes??'—' }} 分钟</span></div><table class="fit-table"><thead><tr><th>动作</th><th>实际组次</th><th>重量</th></tr></thead><tbody><tr v-for="i in detail.items"><td><span class="fit-mini-action"><img v-if="fs.exercise(i.exerciseId)?.image" :src="asset(fs.exercise(i.exerciseId).image)"/>{{ fs.exercise(i.exerciseId)?.name }}</span></td><td>{{ i.sets.length }} × {{ i.sets[0]?.reps??'—' }}</td><td>{{ i.sets[0]?.weight??'—' }} kg</td></tr></tbody></table><p class="fit-note">{{ detail.notes||'暂无备注' }}</p><div class="fit-actions"><button class="fit-button" @click="edit(detail)">编辑记录</button><button class="fit-button" @click="copy(detail)">复制为新记录</button></div></div></template><div v-else class="fit-empty">这一天还没有训练记录。<button class="fit-primary" @click="newRecord(selectedDate)">＋ 补录训练</button></div></section><section class="fit-card"><header><h2>当日计划参考</h2><button class="fit-text" @click="showDifference=!showDifference">{{ showDifference?'收起差异':'查看差异' }}</button></header><p>{{ dayOn(fs.data,selectedDate)?.title||'尚未安排计划' }}</p><p class="fit-muted">计划 {{ dayOn(fs.data,selectedDate)?.items.length??0 }} 个动作 · 实录 {{ calendarRecords.reduce((a,r)=>a+r.items.length,0) }} 个动作</p><p class="fit-muted">{{ dayOn(fs.data,selectedDate)?.notes }}</p><div v-if="showDifference"><div class="fit-list-item" v-for="i in dayOn(fs.data,selectedDate)?.items"><span>{{ fs.exercise(i.exerciseId)?.name }}</span><small>计划{{ i.sets.length }}组 / 实录{{ calendarRecords.flatMap(r=>r.items).filter(a=>a.exerciseId===i.exerciseId).reduce((n,a)=>n+a.sets.length,0) }}组</small></div></div></section><section class="fit-card fit-record-next"><div><h2><AppIcon name="sun"/>下一步</h2><p class="fit-muted">可以从计划带入，再按实际完成情况补录。</p></div><button class="fit-button" @click="newRecord(selectedDate)">＋ 补录训练</button></section></aside></div>
 <template v-if="page==='stats'">
  <div class="fit-kpis"><section class="fit-card"><span class="fit-kpi-symbol mint"><AppIcon name="fitness" :size="27"/></span><small>已记录训练</small><strong>{{ filtered.length }} <small>次</small></strong><p>仅统计已录入记录</p></section><section class="fit-card"><span class="fit-kpi-symbol lavender"><AppIcon name="clock" :size="26"/></span><small>累计时长</small><strong>{{ Math.floor(minutes/60) }}<small>小时</small>{{ minutes%60 }}<small>分</small></strong><p>{{ durationCount }} 次填写时长</p></section><section class="fit-card"><span class="fit-kpi-symbol peach"><AppIcon name="collection" :size="26"/></span><small>已记录容量</small><strong>{{ (totalVolume/1000).toFixed(1) }} <small>t</small></strong><p>仅含已填写重量与次数</p></section><section class="fit-card"><span class="fit-kpi-symbol lavender"><AppIcon name="grid" :size="26"/></span><small>覆盖训练类型</small><strong>{{ types.length }} <small>类</small></strong><p>{{ types.join(' · ')||'暂无记录' }}</p></section></div><div v-if="comparePrevious" class="fit-note">上一时段 {{ previous.length }} 次训练 · 容量 {{ (volume(previous.flatMap(r=>r.items))/1000).toFixed(1) }} t · 本期相差 {{ filtered.length-previous.length }} 次</div>
  <div class="fit-stat-grid"><section class="fit-card"><header><div><h2>▥ 训练频次分布</h2><p class="fit-muted">{{ filtered.length }} 次训练记录</p></div><select v-model="group"><option>按周</option><option>按周期</option><option>按月</option></select></header><FitnessChart :labels="chartLabels" :values="buckets.map(b=>b.records.length)" :series="chartSeries" bars unit="次"/><div class="fit-chart-legend"><span v-for="p in proportions" :style="{color:p.color}">● {{ p.type }} {{ p.count }}次</span></div></section><section class="fit-card fit-type-chart"><h2>训练类型分布</h2><div class="fit-donut-row"><div class="fit-donut" :style="{background:filtered.length?donut:'var(--line)'}"><div><strong>{{ filtered.length }}</strong><small>次训练</small></div></div><div><p v-for="p in proportions"><i :style="{background:p.color}"/>{{ p.type }}　{{ p.count }}次　{{ Math.round(p.count/filtered.length*100) }}%</p><p v-if="!filtered.length">暂无数据</p></div></div></section><section class="fit-card fit-volume-card"><header><h2>训练{{ metric }}趋势</h2><select v-model="metric"><option>容量</option><option>时长</option><option>次数</option></select><button class="fit-text" @click="exportChart($event)">导出图表</button></header><FitnessChart :labels="chartLabels" :values="trend" :unit="metric==='容量'?'t':metric==='时长'?'分钟':'次'"/></section><section class="fit-card fit-month-chart"><header><h2>月度节奏</h2><el-date-picker v-model="month" type="month" format="YYYY 年 M 月" value-format="YYYY-MM" :clearable="false"/></header><div class="fit-heatmap"><div v-for="d in calendar" :class="{filled:fs.data.records.some(r=>r.date===d),outside:!d.startsWith(month)}" :title="d+' · '+fs.data.records.filter(r=>r.date===d).length+'次'">{{ Number(d.slice(8)) }}</div></div><p class="fit-muted">颜色表示有训练记录，无记录日期不自动判定为休息。</p></section></div><p class="fit-muted fit-footnote">时长为手动填写；容量为重量 × 次数之和。不同动作的重量口径可能不同，建议在动作对比中查看单个动作的变化。</p>
 </template>
 <template v-if="page==='compare'">
  <section class="fit-card fit-compare-toolbar"><label>动作<select v-model="actionId"><option v-for="e in actions" :value="e.id">{{ e.name }}</option></select></label><label>时间范围<el-date-picker v-model="dateFrom" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/> — <el-date-picker v-model="dateTo" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/></label><div class="fit-segment"><button class="active" @click="($refs.trendPanel as HTMLElement)?.scrollIntoView({block:'nearest'})">趋势</button><button @click="($refs.comparePanel as HTMLElement)?.scrollIntoView({block:'nearest'})">两次对比</button></div><span>计量单位　{{ actionUnit }}</span></section>
  <p v-if="!actionHistory.length" class="fit-card fit-empty">还没有包含动作明细的历史记录，补录后可查看动作趋势。</p>
  <template v-else><div class="fit-compare-kpis"><section class="mint"><DesignArt kind="mint"/><div><small>最近一次</small><strong>{{ actionB?maxWeight(actionB):0 }} {{ actionUnit }}<span v-if="actionUnit==='kg'"> × {{ actionB?actionItems(actionB)[0]?.sets[0]?.reps??'—':'—' }}次</span></strong><small>{{ actionB?.date.slice(5) }}</small></div></section><section class="lavender"><span class="fit-kpi-symbol"><AppIcon name="grid"/></span><div><small>{{ actionMetric }}</small><strong>{{ Math.max(...actionHistory.map(maxWeight)) }} {{ actionUnit }}</strong><small>{{ actionB?.date.slice(5) }}</small></div></section><section class="blue"><span class="fit-kpi-symbol"><AppIcon name="document"/></span><div><small>已记录</small><strong>{{ actionHistory.length }} 次</strong><small>当前时段</small></div></section><p>同一动作，同一计量方式对比。</p></div>
  <div class="fit-compare-trend-row" ref="trendPanel"><section class="fit-card"><header><h2><AppIcon name="grid"/>历次表现</h2><div class="fit-segment"><button v-for="o in actionOptions" :class="{active:actionMetric===o}" @click="actionMetric=o">{{ o }}</button></div></header><FitnessChart :labels="actionHistory.map(r=>r.date.slice(5))" :values="actionValues" :unit="actionMetric==='总次数'?'次':actionUnit"/></section><section v-if="actionB" class="fit-card fit-compare-snapshot"><h2><AppIcon name="calendar"/>记录详情</h2><div class="fit-compare-snapshot-body"><DesignArt kind="mint"/><h2>{{ actionB.date.slice(5) }} <span class="fit-badge">最近一次</span></h2><p>{{ fs.exercise(actionId)?.name }}</p><dl><dt>记录值</dt><dd>{{ maxWeight(actionB) }} {{ actionUnit }}</dd><dt>次数</dt><dd>{{ reps(actionB) }} 次</dd><dt>组数</dt><dd>{{ setCount(actionItems(actionB)) }} 组</dd><dt>训练容量</dt><dd>{{ volume(actionItems(actionB)) }} kg</dd></dl></div><button class="fit-wide-button" @click="selectedDate=actionB.date;selectedId=actionB.id;emit('navigate','calendar')">查看当次训练 →</button></section></div>
  <div class="fit-compare-bottom" ref="comparePanel"><section class="fit-card"><h2><AppIcon name="grid"/>两次训练对比</h2><div class="fit-comparison"><div v-for="(r,i) in [actionA,actionB]" :key="i" :class="i===0?'mint':'lavender'"><select :value="i===0?(aId||actionA?.id):(bId||actionB?.id)" @change="i===0?aId=($event.target as HTMLSelectElement).value:bId=($event.target as HTMLSelectElement).value"><option v-for="r in actionHistory" :value="r.id">{{ r.date }}</option></select><div class="fit-compare-title"><DesignArt :kind="i===0?'mint':'lavender'"/><div><h3>{{ fs.exercise(actionId)?.name }}</h3><strong>{{ r?maxWeight(r):0 }} {{ actionUnit }} × {{ r?actionItems(r)[0]?.sets[0]?.reps??'—':'—' }} 次</strong></div></div><div class="fit-compare-totals"><span>总次数<b>{{ r?reps(r):0 }}次</b></span><span>训练容量<b>{{ r?volume(actionItems(r)):0 }} kg</b></span></div></div></div><p v-if="actionA&&actionB" class="fit-compare-delta">记录值相差 <b>{{ maxWeight(actionB)-maxWeight(actionA) }} {{ actionUnit }}</b>　容量相差 <b>{{ volume(actionItems(actionB))-volume(actionItems(actionA)) }} kg</b></p></section><section class="fit-card"><h2>历史记录</h2><table class="fit-table"><thead><tr><th>日期</th><th>记录值</th><th>次数</th><th>组数</th><th>容量</th></tr></thead><tbody><tr v-for="r in [...actionHistory].reverse()"><td>{{ r.date.slice(5) }}</td><td>{{ maxWeight(r) }} {{ actionUnit }}</td><td>{{ reps(r) }}</td><td>{{ setCount(actionItems(r)) }}</td><td>{{ volume(actionItems(r)) }} kg</td></tr></tbody></table><p class="fit-muted fit-footnote">只比较已填写的数据，不同动作不混算。</p></section></div></template>
 </template>
 <template v-if="page==='list'">
  <section class="fit-card fit-list-filters"><div class="fit-list-dates"><el-date-picker v-model="dateFrom" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/> — <el-date-picker v-model="dateTo" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/></div><input v-model="query" placeholder="搜索训练、动作或备注"/><select v-model="type"><option>全部</option><option v-for="t in ['推','拉','腿','有氧','自定义']">{{ t }}</option></select><select v-model="source"><option>全部</option><option>手动补录</option><option>导入</option></select><span>共 {{ filtered.length }} 条记录 · 已选择 {{ checked.length }} 条</span><button class="fit-button" @click="query='';type='全部';source='全部'">重置</button></section><div class="fit-columns"><section class="fit-card"><table class="fit-table fit-record-list"><thead><tr><th></th><th>日期</th><th>训练内容</th><th>动作数</th><th>手填用时</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered.slice((pageNumber-1)*8,pageNumber*8)" :class="{selected:selectedId===r.id}" @click="selectedId=r.id"><td><input type="checkbox" v-model="checked" :value="r.id" @click.stop/></td><td>{{ r.date.slice(5) }}</td><td><span class="fit-badge" :class="tone(r.type)">{{ r.title }}</span></td><td>{{ r.items.length }}</td><td>{{ r.minutes===null?'—':r.minutes+'分钟' }}</td><td>{{ r.source }}</td><td><button class="fit-icon" @click.stop="edit(r)" aria-label="编辑记录">✎</button><button class="fit-icon" @click.stop="remove(r)" aria-label="删除记录">×</button></td></tr></tbody></table><p class="fit-empty" v-if="!filtered.length">暂无记录，可手动补录或导入历史数据。</p><div class="fit-pagination"><small>— 表示未填写，不按 0 处理。</small><button @click="pageNumber--" :disabled="pageNumber===1">‹</button><span>{{ pageNumber }} / {{ Math.max(1,Math.ceil(filtered.length/8)) }}</span><button @click="pageNumber++" :disabled="pageNumber*8>=filtered.length">›</button></div></section><aside class="fit-side-column"><section class="fit-card fit-list-detail" v-if="detail"><header><h2><AppIcon name="calendar" :size="18"/>训练记录详情</h2><small>最后修改：{{ detail.updated.slice(5,10) }}</small></header><div class="fit-list-detail-heading"><p>{{ detail.date }} <span class="fit-badge">{{ detail.source }}</span></p><h2><AppIcon name="fitness"/>{{ detail.title }}</h2><DesignArt kind="hero"/></div><div class="fit-record-metrics"><span>{{ detail.items.length }} 个<small>动作</small></span><span>{{ setCount(detail.items) }} 组<small>实际组次</small></span><span>{{ detail.minutes??'—' }} 分钟<small>手填用时</small></span></div><h3>动作明细</h3><table class="fit-table"><thead><tr><th>#</th><th>动作</th><th>实际组次</th><th>实际重量</th></tr></thead><tbody><tr v-for="(i,n) in detail.items"><td>{{ String(n+1).padStart(2,'0') }}</td><td><span class="fit-mini-action"><img v-if="fs.exercise(i.exerciseId)?.image" :src="asset(fs.exercise(i.exerciseId).image)"/>{{ fs.exercise(i.exerciseId)?.name }}</span></td><td>{{ i.sets.length }} × {{ i.sets[0]?.reps??'—' }}</td><td>{{ i.sets[0]?.weight??'—' }} kg</td></tr></tbody></table><p class="fit-note">备注　{{ detail.notes||'暂无备注' }}</p><div class="fit-actions"><button class="fit-button" @click="edit(detail)"><AppIcon name="edit" :size="15"/>编辑记录</button><button class="fit-button" @click="copy(detail)"><AppIcon name="document" :size="15"/>复制为新记录</button><button class="fit-text" @click="remove(detail)">删除</button></div></section><section class="fit-card"><h2>数据管理</h2><p class="fit-muted">支持 CSV / JSON 导入导出，导入后先预览再保存。</p><button class="fit-button" @click="exportRecords(true)">下载导入模板</button></section></aside></div>
 </template>
 <form v-if="page==='entry'" ref="recordForm" @submit.prevent="saveRecord"><div class="fit-entry-actions" style="display:none"><button type="button" class="fit-button" @click="emit('navigate','calendar')">取消</button><button class="fit-primary">保存记录</button></div><div class="fit-columns"><div class="fit-main-column"><div class="fit-segment fit-entry-mode"><button type="button" :class="{active:summaryOnly}" @click="summaryOnly=true">快速摘要</button><button type="button" :class="{active:!summaryOnly}" @click="summaryOnly=false">动作明细</button><small>只记日期与训练名称也可以，动作和时长可稍后补充。</small></div><section class="fit-card fit-entry-basics"><h2><AppIcon name="document" :size="18"/>基本信息</h2><div class="fit-form-grid"><label>日期<el-date-picker v-model="draft.date" type="date" format="YYYY.MM.DD" value-format="YYYY-MM-DD" :clearable="false"/></label><label>训练名称<input v-model="draft.title" placeholder="例如：背部训练" required/></label><label>训练类型<select v-model="draft.type"><option v-for="t in ['推','拉','腿','有氧','自定义']">{{ t }}</option></select></label><label>用时（可选，手动填写）<input v-model.number="draft.minutes" type="number" min="0" placeholder="分钟"/></label></div><label class="fit-entry-tags"><span>自定义标签</span><input v-model="draft.tags" placeholder="添加标签…（可选）"/></label><div class="fit-filter-chips fit-entry-source"><span>内容来源</span><button type="button" v-for="m in ['空白补录','从计划带入','从模板带入']" :class="{active:sourceMode===m}" @click="bring(m)">{{ m }}</button><select v-if="sourceMode==='从模板带入'" v-model="recordTemplate" @change="bring('从模板带入')"><option value="">选择模板</option><option v-for="t in fs.data.templates" :value="t.id">{{ t.title }}</option></select></div><p v-if="sourceMode!=='空白补录'" class="fit-note fit-entry-source-note">已带入{{ sourceMode==='从计划带入'?'计划':'模板' }}，请按实际完成情况修改。</p></section><section class="fit-card" v-if="!summaryOnly"><h2>动作明细 <small>{{ draft.items.length }}个动作 · {{ setCount(draft.items) }}组</small></h2><ItemEditor :items="draft.items" actual/></section></div><aside class="fit-side-column"><section class="fit-card fit-entry-summary"><h2><AppIcon name="document"/>本次记录</h2><DesignArt class="fit-entry-equipment" kind="lavender"/><dl><dt><AppIcon name="calendar" :size="15"/>日期</dt><dd>{{ draft.date }}</dd><dt><AppIcon name="fitness" :size="15"/>训练类型</dt><dd>{{ draft.type }}</dd><dt><AppIcon name="list" :size="15"/>动作与组数</dt><dd>{{ draft.items.length }} 个动作 · {{ setCount(draft.items) }} 组</dd><dt><AppIcon name="clock" :size="15"/>用时</dt><dd>{{ draft.minutes??'—' }} 分钟 <small>手填</small></dd><dt><AppIcon name="collection" :size="15"/>自定义标签</dt><dd>{{ draft.tags||'—' }}</dd></dl><label class="fit-label">本次备注<textarea v-model="draft.notes" placeholder="记录这次训练的感受（可选）" rows="4"/></label></section><details class="fit-card fit-extra-fields"><summary><AppIcon name="collection" :size="16"/>自定义附加项（可选）</summary><label class="fit-label">场地、感受等<textarea v-model="draft.extra" placeholder="按需要自由填写"/></label></details><section class="fit-card fit-help-card"><h2><AppIcon name="sun"/>补录很轻松</h2><div><p><b>✓ 可以仅保存摘要</b><small>只记日期和训练名称也可以，动作和时长可稍后补充。</small></p><p><b>✓ 可以引用计划或模板再修改</b><small>按实际完成情况调整。</small></p><p><b>✓ 留空数据不会被当作 0</b><small>不填写的内容保持为空。</small></p></div><DesignArt kind="note-character"/></section><div class="fit-entry-save-actions"><button type="button" class="fit-button" @click="previewRecord=!previewRecord"><AppIcon name="search" :size="16"/>预览记录</button><button class="fit-primary">▣ 保存并返回记录</button></div><section v-if="previewRecord" class="fit-card"><h3>{{ draft.date }} · {{ draft.title }}</h3><p>{{ draft.items.length }} 个动作 · {{ setCount(draft.items) }} 组 · {{ draft.minutes??'—' }} 分钟</p></section></aside></div></form>
 </div>
</template>
